#include "ksSquareRootCalls.h"
#include "ksControllerBoundary.h"
#include <stdexcept>
namespace ks{namespace{SquareRootPartialTest partialTest=nullptr;using S=SquareRootTask::Stage;struct Point{unsigned location,length;};Point point(const SquareRootTask&t){switch(t.stage()){case S::Retain:return {0x9e28,2};case S::Clear:return {0x9e2a,2};case S::SetTrial:return {0x9e2c,2};case S::AddTrial:return {0x9e2e,2};case S::CaptureCandidate:return {0x9e30,2};case S::Square:return {0x9e32,2};case S::Compare:return {0x9e34,2};case S::Admit:return {0x9e36,2};case S::Reject:return {0x9e38,2};case S::HalfTrial:return {0x9e3a,2};case S::AdmitMore:return {0x9e3c,2};case S::Restore:return {0x9e3e,2};case S::Finish:return {0x9e40,2}; default:break;}throw std::runtime_error("Invalid native square root stage");}}
bool SquareRootCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x9e28){if(selected)throw std::runtime_error("Overlapping native square root caller");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Native square root capacity exceeded");selected->emplace(h.getSP());++started;}
 if(!selected||point((*selected)->task).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&task=(**selected).task;auto&v=h.regs;auto stage=task.stage();auto before=h.cycles;Boundary f(h,pc,point(task).length);auto cost=task.nextClocks();if(task.advanceBefore(cost,[&]{return uint16_t(v[0].e);})!=cost)throw std::runtime_error("Native square root admission mismatch");switch(stage){case S::Retain:f.push(v[1].r);(**selected).depth+=2;break;case S::Clear:v[0].rl=h.sub8(v[0].rl,v[0].rl);break;case S::SetTrial:f.move(v[0].rh,128);break;case S::AddTrial:v[0].rl=h.add8(v[0].rl,v[0].rh);break;case S::CaptureCandidate:f.move(v[1].rl,v[0].rl);break;case S::Square:v[1].r=int16_t(task.square());h.clockI(12);break;case S::Compare:h.sub16(v[1].r,v[0].e);break;case S::Reject:v[0].rl=h.sub8(v[0].rl,v[0].rh);break;case S::HalfTrial:f.shift(v[0].rh,1,false);break;case S::Restore:f.pop(v[1].r);(**selected).depth-=2;break;case S::Finish:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;if(h.cycles-before!=cost)throw std::runtime_error("Native square root return clocks differ");return true;default:break;}
 if(uint8_t(v[0].rl)!=task.result()&&stage!=S::Retain)throw std::runtime_error("Native square root result projection differs");if(h.cycles-before!=cost)throw std::runtime_error("Native square root clocks differ");h.pc=h.makepc(point(task).location);return true;}
}

